; GENERATED by tools/make_strip.py - copied to BUFF at the start (157 of 160 bytes)
; the small letters, 3 x 5: 15 bits each, top-left first (A-Z ! . - ')
lfont_src:
        defb 0x57,0xDA   ; A
        defb 0xD7,0x5C   ; B
        defb 0x72,0x46   ; C
        defb 0xD6,0xDC   ; D
        defb 0xF3,0x4E   ; E
        defb 0xF3,0x48   ; F
        defb 0x72,0xD6   ; G
        defb 0xB7,0xDA   ; H
        defb 0xE9,0x2E   ; I
        defb 0x24,0xD4   ; J
        defb 0xB7,0x5A   ; K
        defb 0x92,0x4E   ; L
        defb 0xBF,0xDA   ; M
        defb 0xD6,0xDA   ; N
        defb 0x56,0xD4   ; O
        defb 0xD7,0x48   ; P
        defb 0x56,0xE6   ; Q
        defb 0xD7,0x5A   ; R
        defb 0x71,0x1C   ; S
        defb 0xE9,0x24   ; T
        defb 0xB6,0xDE   ; U
        defb 0xB6,0xD4   ; V
        defb 0xB7,0xFA   ; W
        defb 0xB5,0x5A   ; X
        defb 0xB5,0x24   ; Y
        defb 0xE5,0x4E   ; Z
        defb 0x49,0x04   ; !
        defb 0x00,0x04   ; .
        defb 0x03,0x80   ; -
        defb 0x48,0x00   ; '
; the NOS icon for a slot: 12 rows, 2 bytes each (its byte pair centred)
nos_icon_src:
        defb 0x03,0xC0
        defb 0x00,0x80
        defb 0x03,0xC0
        defb 0x07,0xE0
        defb 0x08,0x10
        defb 0x0A,0x10
        defb 0x0F,0xF0
        defb 0x0F,0xF0
        defb 0x0F,0xF0
        defb 0x0A,0x10
        defb 0x08,0x10
        defb 0x07,0xE0
NOS_ROWS equ 12
; the crew chief's messages, by number (their addresses once copied): lines split
; by |, ended by 0
msg_index_src:
        dw M_LUCK_t - buff_src + BUFF
        dw M_PASS_t - buff_src + BUFF
        dw M_P1_t - bufh_src + BUFH
        dw M_LOST_t - bufh_src + BUFH
        dw M_PUSH_t - bufh_src + BUFH
        dw M_BEST_t - bufh_src + BUFH
        dw M_HIT_t - bufh_src + BUFH
        dw M_LAST_t - bufh_src + BUFH
        dw M_WIN_t - bufh_src + BUFH
        dw M_DONE_t - bufe_src + BUFE
        dw M_NOS_t - bufg_src + BUFG
        dw M_BOOST_t - bufe_src + BUFE
        dw M_SETUP_t - bufg_src + BUFG
M_LUCK equ 0
M_LUCK_t:
        db "GOOD LUCK!|SPACE FOR NOS",0
M_PASS equ 1
M_PASS_t:
        db "GREAT MOVE!|NICE PASS",0
